export const adminLanguages: {code:AdminLanguage;name:string}[] = [{code:'en',name:'English'},{code:'fr',name:'Français'},{code:'es',name:'Español'},{code:'pt',name:'Português'},{code:'de',name:'Deutsch'},{code:'it',name:'Italiano'},{code:'tr',name:'Türkçe'},{code:'ar',name:'العربية'},{code:'hi',name:'हिन्दी'},{code:'zh',name:'中文'}];
export function adminTranslate(language: string, key: AdminKey): string { return language === 'en' ? adminEnglish[key] : translations[language as Exclude<AdminLanguage,'en'>]?.[key] || adminEnglish[key]; }
export const adminTranslationKeys = Object.keys(adminEnglish) as AdminKey[];
export const adminTranslationCoverage = Object.fromEntries(adminLanguages.map(({code})=>[code,code==='en'?adminTranslationKeys.length:Object.keys(translations[code]).length]));
